# ACTION 1: robust detection with fallbacks and graceful handling of errors
try:
    image_1_cup_detection, image_1_cup_boxes = detection(image_1, ["measuring cup", "cup"])
    display(image_1_cup_detection.annotated_image)
    print("Detected boxes:", image_1_cup_boxes)
except Exception as e:
    print("Primary detection failed with error:", repr(e))
    print("Attempting sliding window detection as a fallback...")
    try:
        possible_patches, possible_boxes = sliding_window_detection(image_1, ["measuring cup", "cup"])
        if possible_patches:
            for i, patch in enumerate(possible_patches):
                print(f"Patch {i+1}:")
                display(patch.annotated_image)
                # print bounding boxes for this patch if available
                if i < len(possible_boxes):
                    print(f"Boxes in patch {i+1}:", possible_boxes[i])
                else:
                    print(f"No boxes list available for patch {i+1}.")
        else:
            print("sliding_window_detection returned no patches. Displaying the original image for manual inspection.")
            display(image_1)
    except Exception as e2:
        print("sliding_window_detection also failed with error:", repr(e2))
        print("As a last resort, displaying the original image for manual inspection.")
        display(image_1)
